{"command":"cat > /workspace/fix_drums.py << 'PYEOF'
#!/usr/bin/env python3
"""Fix drums: put kick ch0, snare ch1, hats on ch7 carefully, or restructure.

Current layout conflicts on ch1. New layout:
ch0 kick, ch1 snare, ch2 bass, ch3 lead, ch4 arp, ch5 pad, ch6 harmony/pluck, ch7 hats+bells

We'll clear ch0, ch1, ch7 for patterns 0-6 and rewrite drums + bells.
"""
import json

def cell(pattern, row, ch, note=None, ins=None, vol=None, fx=None, fp=None):
    d = {"pattern": pattern, "row": row, "channel": ch}
    if note is not None: d["note"] = note
    if ins is not None: d["instrument"] = ins
    if vol is not None: d["volume"] = vol
    if fx is not None: d["effect"] = fx
    if fp is not None: d["effect_param"] = fp
    return {"name": "pattern_set_cell", "arguments": d}

def clear_cell(p, r, ch):
    return {"name": "cell_clear", "arguments": {"pattern": p, "row": r, "channel": ch}}

ops = []

# Clear channels 0, 1, 7 entirely for patterns 0-6 (drums + hats/bells)
for p in range(7):
    for r in range(64):
        for ch in (0, 1, 7):
            ops.append(clear_cell(p, r, ch))

def drums_full(ops, p, snare_ch=1, hat_ch=7):
    for r in range(64):
        beat = r % 16
        # Kick ch0
        if beat in (0, 8):
            ops.append(cell(p, r, 0, "C-4", 8, 64))
        elif beat == 10 and (r // 16) % 2 == 1:
            ops.append(cell(p, r, 0, "C-4", 8, 32))
        elif beat == 6 and r % 32 >= 16:
            ops.append(cell(p, r, 0, "C-4", 8, 30))
        # Snare
        if beat == 4:
            ops.append(cell(p, r, snare_ch, "C-4", 9, 56))
        elif beat == 12:
            ops.append(cell(p, r, snare_ch, "C-4", 9, 50))
        elif beat == 14 and r % 32 == 30:
            ops.append(cell(p, r, snare_ch, "C-4", 9, 28))  # ghost
        # Hats on hat_ch - only when no snare conflict... hats on separate ch
        if beat % 2 == 0:
            v = 30 if beat % 4 == 0 else 22
            if beat not in (4, 12):  # keep hats on even when snare - separate ch
                ops.append(cell(p, r, hat_ch, "C-5", 10, v))
            else:
                ops.append(cell(p, r, hat_ch, "C-5", 10, 16))  # soft under snare
        if beat == 15 and r % 16 == 15:
            ops.append(cell(p, r, hat_ch, "C-4", 11, 24))  # open hat end of bar sometimes
        if beat == 7 and (r // 16) % 2 == 0:
            ops.append(cell(p, r, hat_ch, "C-4", 11, 20))

def drums_intro(ops, p):
    for r in range(64):
        beat = r % 16
        if r >= 0 and beat == 0 and r % 32 == 0:
            ops.append(cell(p, r, 0, "C-4", 8, 42))
        if r >= 32 and beat % 4 == 0:
            ops.append(cell(p, r, 7, "C-5", 10, 18))
        if r >= 48 and beat in (4, 12):
            ops.append(cell(p, r, 1, "C-4", 9, 36))
        if r >= 56 and beat in (0, 4, 8, 12):
            ops.append(cell(p, r, 0, "C-4", 8, 40 + (r - 56)))
    ops.append(cell(p, 60, 0, "C-4", 8, 55))
    ops.append(cell(p, 62, 0, "C-4", 8, 50))
    ops.append(cell(p, 63, 1, "C-4", 9, 48))

def drums_break(ops, p):
    for r in range(64):
        beat = r % 16
        if beat in (0, 8):
            ops.append(cell(p, r, 0, "C-4", 8, 48))
        if beat == 4:
            ops.append(cell(p, r, 1, "C-4", 9, 40))
        if beat in (2, 6, 10, 14):
            ops.append(cell(p, r, 7, "C-5", 10, 22))
        if beat == 6:
            ops.append(cell(p, r, 7, "C-4", 11, 24))

def drums_build(ops, p):
    for r in range(64):
        beat = r % 16
        if beat in (0, 4, 8, 12):
            ops.append(cell(p, r, 0, "C-4", 8, 58))
        if beat in (4, 12):
            ops.append(cell(p, r, 1, "C-4", 9, 52))
        # 8th hats
        if beat % 2 == 0:
            ops.append(cell(p, r, 7, "C-5", 10, 28))
        else:
            ops.append(cell(p, r, 7, "C-5", 10, 16))
        # rolling kicks at end
        if r >= 56:
            if beat % 2 == 0:
                ops.append(cell(p, r, 0, "C-4", 8, 45 + (r - 56) * 2))
    # toms
    ops.append(cell(p, 60, 0, "F-3", 12, 48))
    ops.append(cell(p, 62, 0, "D-3", 12, 52))
    ops.append(cell(p, 63, 0, "C-3", 12, 56))

# Apply drum styles
drums_intro(ops, 0)
drums_full(ops, 1)
drums_full(ops, 2)
# toms on pattern 2 end - overwrite kick
ops.append(cell(2, 60, 0, "F-3", 12, 48))
ops.append(cell(2, 62, 0, "D-3", 12, 52))
ops.append(cell(2, 63, 0, "C-3", 12, 58))

drums_full(ops, 3)
drums_break(ops, 4)
drums_build(ops, 5)
drums_full(ops, 6)

# Re-add bells on channel 7 carefully - they conflict with hats!
# Better move bells to share with harmony? Or put bells only on empty hat rows.
# Actually let's put bells on ch6 together? Ch6 has pluck/harmony.
# For patterns with bells, place them on rows where hat is soft/none, OR use volume.
# Simplest: put bells back where they were - on ch7, overwriting hats on those rows only.

# Pattern 0 intro bells were on ch6 - leave them
# Pattern 2 bells on ch7:
for r, n in [(4, "E-5"), (20, "E-5"), (36, "A-5"), (52, "A-5")]:
    ops.append(cell(2, r, 7, n, 13, 30))

# Pattern 4 bells
bells4 = [(2, "E-6"), (10, "B-5"), (18, "A-5"), (26, "E-6"),
          (34, "D-6"), (42, "A-5"), (50, "G-5"), (58, "B-5")]
for r, n in bells4:
    ops.append(cell(4, r, 7, n, 13, 34))

# Pattern 5 bells
for r, n in [(0, "A-5"), (16, "G-5"), (32, "F-5"), (48, "E-6"), (56, "E-6"), (60, "E-6")]:
    ops.append(cell(5, r, 7, n, 13, 38))

# Pattern 6 bells
for r, n in [(4, "E-5"), (36, "G-5")]:
    ops.append(cell(6, r, 7, n, 13, 28))

print(f"ops: {len(ops)}")
with open("/workspace/fix_drums.json", "w") as f:
    json.dump(ops, f)
